import heapq

def match(orders):
    trades = []
    book = {}  # id -> {'side':..., 'price':..., 'qty':..., 'seq':...}
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    seq_counter = 0

    def push_book(oid, side, price, qty, seq):
        book[oid] = {'side': side, 'price': price, 'qty': qty, 'seq': seq}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                del book[oid]
            continue

        oid = order[1]
        side = order[2]
        if typ == 'market':
            price = None
            qty = order[3]
        else:
            price = order[3]
            qty = order[4]

        seq_counter += 1
        my_seq = seq_counter

        remaining = qty

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0 and opp_heap:
            top = heapq.heappop(opp_heap)
            key, top_seq, top_id = top

            if top_id not in book:
                continue
            info = book[top_id]
            if info['seq'] != top_seq:
                continue
            if info['qty'] <= 0:
                continue

            resting_price = info['price']

            if price is not None:
                if side == 'buy':
                    if resting_price > price:
                        # put back, no match possible, stop
                        heapq.heappush(opp_heap, top)
                        break
                else:
                    if resting_price < price:
                        heapq.heappush(opp_heap, top)
                        break

            trade_qty = min(remaining, info['qty'])
            if side == 'buy':
                buy_id = oid
                sell_id = top_id
            else:
                buy_id = top_id
                sell_id = oid

            trades.append([buy_id, sell_id, resting_price, trade_qty])

            remaining -= trade_qty
            info['qty'] -= trade_qty

            if info['qty'] <= 0:
                if top_id in book and book[top_id]['seq'] == top_seq:
                    del book[top_id]
            else:
                heapq.heappush(opp_heap, top)

        if typ == 'limit' and remaining > 0:
            push_book(oid, side, price, remaining, my_seq)

    return trades

